import React, { useEffect, useState } from 'react';
import '../Estilos/ReservasEspeciales.css';

function ReservasEspeciales() {
  const [error, setError] = useState("");
  const [reservasEspeciales, setreservasEspeciales] = useState([]);
  const [mesesReservados, setmesesReservados] = useState([]);
  const [diasReservados, setdiasReservados] = useState([]);
  const [horasDesdeReservadas, setHorasDesdeReservadas] = useState([]);
  const [horasHastaReservadas, setHorasHastaReservadas] = useState([]);
  const setErrorWithTimeout = (message) => {
    setError(message);
    setTimeout(() => {
      setError("");
    }, 2000);
  };

  const fetchReservasEspeciales = async () => {
    const token = localStorage.getItem('token');
      if(!token){
        setErrorWithTimeout('No se encontró el token de autenticación.');
        return;
      }

    try {
      const response = await fetch('http://localhost:5000/get_special_requests', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
        },
      });

      if (response.ok) {
        const data = await response.json();
        setreservasEspeciales(data);

      } else {
        const errorData = await response.json();
        setErrorWithTimeout(errorData.error || 'Error al obtener las reservas especiales.')
      }
    } catch (error) {
      console.error('Error de red:', error);
      setErrorWithTimeout('Error al conectar con el servidor.')
    }
  };
  
  useEffect(() => {
    fetchReservasEspeciales();
  },[]);

  const obtenerMeses = () => {
    const reservasFiltradas = reservasEspeciales.filter((reserva) => {
      return reserva.tipo === "DG";
    });
  
    const mesesReservadosActualizados = [];
  
    reservasFiltradas.forEach((reserva) => {
      const mesesDeReserva = []; 
  
      for (const mes in reserva.meses) {
        if (reserva.meses[mes]) {
          mesesDeReserva.push(mes);
        }
      }
  
      if (mesesDeReserva.length > 0) {
        mesesReservadosActualizados.push(mesesDeReserva); 
      }
    });
  
    setmesesReservados(mesesReservadosActualizados);
  };
  
  const obtenerDias = () => {
    const reservasFiltradas = reservasEspeciales.filter((reserva) => {
      return reserva.tipo === "DG";
    });
  
    const diasReservadosActualizados = [];
  
    reservasFiltradas.forEach((reserva) => {
      const diasDeReserva = []; 
  
      for (const dia in reserva.dias) {
        // Accede a la propiedad 'seleccionado' correctamente
        if (reserva.dias[dia].seleccionado) {
          diasDeReserva.push(dia); 
        }
      }
  
      if (diasDeReserva.length > 0) {
        diasReservadosActualizados.push(diasDeReserva); 
      }
    });
  
    setdiasReservados(diasReservadosActualizados);
  };
  
  const obtenerHoraDesde = () => {
    const reservasFiltradas = reservasEspeciales.filter((reserva) => {
      return reserva.tipo === "DG";
    });
  
    const horaDesdeActualizados = [];
  
    reservasFiltradas.forEach((reserva) => {
      const horaDesdeReserva = []; 
  
      for (const dia in reserva.dias) {
        // Accede a la propiedad 'horaDesde' correctamente
        if (reserva.dias[dia].seleccionado) {
          horaDesdeReserva.push(reserva.dias[dia].horaDesde); // Agrega la hora desde
        }
      }
  
      if (horaDesdeReserva.length > 0) {
        horaDesdeActualizados.push(horaDesdeReserva); // Agrega el array de horas
      }
    });
  
    setHorasDesdeReservadas(horaDesdeActualizados); // Asegúrate de que el estado se llame 'setHorasDesde'
  };

  const obtenerHoraHasta = () => {
    const reservasFiltradas = reservasEspeciales.filter((reserva) => {
      return reserva.tipo === "DG";
    });
  
    const horaHastaActualizados = [];
  
    reservasFiltradas.forEach((reserva) => {
      const horaHastaReserva = []; 
  
      for (const dia in reserva.dias) {
        // Accede a la propiedad 'horaDesde' correctamente
        if (reserva.dias[dia].seleccionado) {
          horaHastaReserva.push(reserva.dias[dia].horaHasta); // Agrega la hora desde
        }
      }
  
      if (horaHastaReserva.length > 0) {
        horaHastaActualizados.push(horaHastaReserva); // Agrega el array de horas
      }
    });
  
    setHorasHastaReservadas(horaHastaActualizados); // Asegúrate de que el estado se llame 'setHorasDesde'
  };
  
  
  useEffect(() => {
    if (reservasEspeciales.length > 0) {
      obtenerMeses();
      obtenerDias();
      obtenerHoraDesde();
      obtenerHoraHasta();
    }
  }, [reservasEspeciales]);


  return (
    <div>
      {error && <div className="error">{error}</div>}
      <h1>Meses Reservados</h1>
      <pre>{mesesReservados}</pre>
      <h1>Días Reservados</h1>
      <pre>{diasReservados}</pre>
      <h1>Horas Desde Reservadas</h1>
      <pre>{horasDesdeReservadas}</pre>
      <h1>Horas Hasta Reservadas</h1>
      <pre>{horasHastaReservadas}</pre>
    </div>
  );
}

export default ReservasEspeciales;
